-- Topic packs (hand-maintained; not generated by `game-db import`).
-- A topic pack is a non-consumable Play product (Monetize > Products > In-app
-- products, same id) that unlocks the subjects mapped to it below. A subject in
-- any pack is locked until the player owns one of its packs; subjects in no
-- pack stay free. Never map a subject that is already free to play today
-- unless you mean to lock it.
--
-- To add a pack (after its subjects exist in Sheets Dump/catalog/subjects.csv):
--   INSERT INTO billing_products (product_id, kind, title, active, sort_order)
--   VALUES ('pack_gk', 'non_consumable', 'General Knowledge Pack', true, 20)
--   ON CONFLICT (product_id) DO UPDATE SET title = EXCLUDED.title, active = EXCLUDED.active,
--                                         sort_order = EXCLUDED.sort_order;
--   INSERT INTO billing_product_subjects (product_id, subject) VALUES ('pack_gk', 'gk_world')
--   ON CONFLICT DO NOTHING;

-- Guard: an active pack must unlock at least one subject, so nobody can buy an empty pack.
DO $$
DECLARE empty_packs text;
BEGIN
    SELECT string_agg(p.product_id, ', ') INTO empty_packs
      FROM billing_products p
     WHERE p.kind = 'non_consumable' AND p.active
       AND NOT EXISTS (SELECT 1 FROM billing_product_subjects s WHERE s.product_id = p.product_id);
    IF empty_packs IS NOT NULL THEN
        RAISE EXCEPTION 'active topic packs with no subjects: %', empty_packs;
    END IF;
END $$;
